import {apprenticePages,apprenticeCases} from './fair-test-apprentice-content.mjs';
import {apprenticeView,setApprenticeOpen,startApprentice,setApprenticePage,changeApprenticeRepair,chooseApprenticeCard,setApprenticeWords,addApprenticeSupport,resumeApprentice,checkApprenticeDemonstration,checkApprenticeCard,keepApprenticeWords,apprenticeCheckMatches} from './fair-test-apprentice-core.mjs';
import {fairRamp} from './fair-test-ramp-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const title=s=>s[0].toUpperCase()+s.slice(1);
const configuration=(source,id)=>source.model.find(c=>c.id===id);
const label=c=>`${title(c.height)} ramp, ${c.surface} landing surface`;
const help='A distance describes what happened in these shown examples. An explanation says why. If height and surface both change, the distances do not isolate one cause. To explore height, keep surface the same. To explore surface, keep height the same. A careful message also says these are model examples, not a promise about every real cart.';
export function apprenticeInvitation(){return `<aside class="apprentice-invitation"><span>Moss is helping the parcel crew.</span> ${button('data-apprentice-open','Help Moss explain a test')}<p id="fair-apprentice-status" role="status" class="tiny"></p></aside>`;}
function pairSummary(source,pair){return `<p class="apprentice-pair-summary">${['a','b'].map(side=>`<strong>${side.toUpperCase()}:</strong> ${esc(label(configuration(source,pair[side])))}`).join('<br>')}</p>`;}
function pairArt(source,pair){return `<div class="apprentice-setups">${['a','b'].map(side=>fairRamp(configuration(source,pair[side]),side.toUpperCase())).join('')}</div>`;}
function valuesTable(source,pair,values=null){const numbers=values||Object.fromEntries(['a','b'].map(side=>[side,configuration(source,pair[side]).distances]));return `<table class="apprentice-values"><caption>Authored model examples · model cm</caption><thead><tr><th scope="col">Example</th><th scope="col">A · model cm</th><th scope="col">B · model cm</th></tr></thead><tbody>${[0,1,2].map(n=>`<tr><th scope="row">${n+1}</th><td>${numbers.a[n]}</td><td>${numbers.b[n]}</td></tr>`).join('')}</tbody></table>`;}
function sourceDetails(r){return `<details class="apprentice-frozen-source"><summary>Original encounter kept with this visit</summary><p><strong>${esc(r.source.question)}</strong></p><blockquote>Moss: “${esc(r.source.claim)}”</blockquote>${pairSummary(r.source,r.source.original)}${pairArt(r.source,r.source.original)}${valuesTable(r.source,r.source.original)}<p class="tiny">Original fiction. These are Moss’s supplied model examples, not measurements collected by the learner.</p></details>`;}
function recordTitle(r,c,index){return `${index===r.checks.length-1&&apprenticeCheckMatches(r,c)?'Latest record of these inputs':'Earlier recorded work'} · ${c.kind==='demonstration'?'comparison demonstration':c.kind==='card'?'supplied explanation':'own words, ungraded'}`;}
function record(r,c,index){return `<section class="apprentice-record" tabindex="-1"><h3 data-apprentice-record-title="${index}">${esc(recordTitle(r,c,index))}</h3>${c.kind==='demonstration'?`<p><strong>Comparison shown:</strong></p>${pairSummary(r.source,c.input)}${c.values?valuesTable(r.source,c.input,c.values):'<p>No values recorded.</p>'}<p><strong>Recorded focused comparison:</strong> ${c.focused===null?'not assessed':c.focused?'yes':'no'}.</p><p class="apprentice-feedback">${esc(c.feedback)}</p><p class="tiny">This demonstration checks the comparison design only. A supplied explanation selected alongside it (${c.input.card?'a supplied explanation':'none'}) was not checked by this action.</p>`:c.kind==='card'?`${c.card?`<p><strong>Recorded supplied explanation:</strong></p><p>${esc(c.card.text)}</p><p><strong>Recorded supplied-card fit:</strong> ${c.card.fits?'useful for Moss’s question':'does not yet address Moss’s need'}.</p><p class="apprentice-feedback">${esc(c.card.feedback)}</p>`:'<p>No supplied card snapshot recorded.</p>'}<p class="tiny">This checks the supplied explanation only; the comparison design was not checked by this action.</p>${c.card&&c.feedback!==c.card.feedback?`<p><strong>Recorded action feedback:</strong> ${esc(c.feedback)}</p>`:''}`:`<p><strong>Own words, ungraded.</strong></p><p class="apprentice-feedback">${esc(c.feedback)}</p>`}<details><summary>${c.kind==='words'?'Exact own words kept':'Own words at this moment — ungraded, not part of this check'}</summary><div class="apprentice-exact">${c.input.words?esc(c.input.words):'<span class="tiny">No own words entered.</span>'}</div></details>${c.kind!=='demonstration'?`<details><summary>Comparison inputs at this moment</summary><p>Selected supplied-card input: ${c.input.card?esc(r.source.cards.find(x=>x.id===c.input.card)?.text||'A supplied explanation'):'none' }.</p>${pairSummary(r.source,c.input)}<p>These inputs are kept without a new comparison outcome.</p></details>`:''}${sourceDetails(r)}</section>`;}
function latest(r){return r.checks.length?record(r,r.checks.at(-1),r.checks.length-1):'';}
function notice(r){return `<h2 id="apprentice-prompt" tabindex="-1">Which part describes, and which part explains why?</h2><p class="apprentice-question"><strong>${esc(r.source.question)}</strong></p><blockquote>Moss: “${esc(r.source.claim)}”</blockquote>${hearButton(`${r.source.question} Moss says: ${r.source.claim}`,'Hear Moss’s question and message')}<p>Talk about the observation and the explanation, or explore another page. There is no answer box for this discussion.</p>${pairArt(r.source,r.source.original)}${pairSummary(r.source,r.source.original)}${valuesTable(r.source,r.source.original)}<p class="tiny">Moss’s supplied model examples. Same cart, no added push; distances begin at the ramp foot. Original fiction, not physical measurements.</p><p>A distance observation can still be useful when a single-cause explanation needs repair. A careful explanation can stay as it is.</p>${button('data-apprentice-page="show"','Show a comparison',true)} ${button('data-apprentice-page="explain"','Choose words for Moss')}${latest(r)}`;}
function showPage(r){const factor=r.source.mission==='height'?'surface':'height';return `<h2 id="apprentice-prompt" tabindex="-1">What comparison could you show Moss?</h2><p class="apprentice-question"><strong>${esc(r.source.question)}</strong></p><p>Keep the question’s settings fixed. Choose the ${factor==='surface'?'surface':'height'} on each side.</p><div class="apprentice-repair-controls">${['a','b'].map(side=>{const original=configuration(r.source,r.source.original[side]),current=configuration(r.source,r.repair[side]),options=r.source.model.filter(c=>c[r.source.mission]===original[r.source.mission]);return `<section><h3>Setup ${side.toUpperCase()}</h3><p><strong>Fixed ${r.source.mission}:</strong> ${esc(title(current[r.source.mission]))}</p><label for="apprentice-${side}">${title(factor)}</label><select id="apprentice-${side}" data-apprentice-repair="${side}">${options.map(c=>`<option value="${c.id}"${c.id===current.id?' selected':''}>${esc(title(c[factor]))}</option>`).join('')}</select></section>`;}).join('')}</div>${button('data-apprentice-demonstrate','Show this comparison to Moss',true)}<p class="tiny">This explicit action checks the comparison design. Supplied explanation and own words stay separate.</p>${latest(r)}${pairArt(r.source,r.repair)}${pairSummary(r.source,r.repair)}${sourceDetails(r)}${button('data-apprentice-page="explain"','Choose an explanation')}`;}
function explain(r){return `<h2 id="apprentice-prompt" tabindex="-1">Which words would help Moss?</h2><p class="apprentice-question"><strong>${esc(r.source.question)}</strong></p><blockquote>Moss: “${esc(r.source.claim)}”</blockquote><p>Help Moss keep a useful observation, limit an overclaim, or recognize a careful message.</p><div class="apprentice-cards" role="group" aria-label="Supplied explanations for Moss">${r.source.cards.map(c=>button(`data-apprentice-card="${c.id}" aria-pressed="${r.selectedCard===c.id}"`,`${c.text}${r.selectedCard===c.id?' · selected':''}`,r.selectedCard===c.id)).join('')}${button('data-apprentice-card="clear"','Leave supplied explanation blank')}</div>${button('data-apprentice-check-card'+(r.selectedCard?'':' disabled'),'Show our supplied explanation',true)}${latest(r)}<section class="apprentice-own-words"><label for="apprentice-words"><strong>Our explanation for a person</strong> (optional)</label><textarea id="apprentice-words" maxlength="800" rows="4" aria-describedby="apprentice-words-help"></textarea><p class="tiny" id="apprentice-words-help">Up to 800 characters in the browser’s text limit. Spaces and line breaks stay exact. Your words are ungraded; no Moss reply is generated from them. They stay with this explorer’s browser work and notes download.</p>${button('data-apprentice-keep-words','Keep our words')}<p class="tiny">Talking, drawing, signing, AAC and explaining away from the screen are welcome and unobserved.</p></section><details id="apprentice-draft" data-visit="${r.id}"><summary>Our comparison draft</summary>${pairSummary(r.source,r.repair)}${pairArt(r.source,r.repair)}</details>${sourceDetails(r)}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="apprentice-catalog"><h2>Choose an encounter with Moss</h2><p>Any encounter is open, including one with a careful explanation.</p><p class="tiny">Up to 12 readable encounters stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'encounter':'encounters'}.`:' Earlier encounters wait within that limit.'}</p>${apprenticeCases.map(c=>`<p>${button(`data-apprentice-start="${c.id}"`,c.title)}</p>`).join('')}</section>`;}
function earlier(v){return `${v.rounds.length?`<details><summary>Our encounters (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-apprentice-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function apprenticePage(state){const v=apprenticeView(state),r=v.current,heading=`<header class="page-heading">${button('data-apprentice-close','Back to my Fair Test Bench')}<h1>Help Moss explain a test</h1><p>Moss is helping the parcel crew compare ramps after the storm. What can a careful comparison tell us?</p></header>`;if(v.status==='unavailable')return `<div class="apprentice-page">${heading}<section class="apprentice-sheet"><h2>Earlier work is safe</h2><p>This apprentice work uses a format we cannot continue here. It remains unchanged. You can return to the ordinary bench.</p><details><summary>See saved apprentice work</summary><pre>${esc(JSON.stringify(state.fairTests?.apprentice,null,2))}</pre></details></section></div>`;
 return `<div class="apprentice-page">${heading}<section class="apprentice-sheet"><nav class="apprentice-tabs" aria-label="Moss encounter pages">${apprenticePages.map(p=>button(`data-apprentice-page="${p}" aria-current="${v.page===p?'page':'false'}"`,title(p),v.page===p)).join('')}</nav>${r?`<p class="apprentice-visit"><strong>${esc(r.source.title)}</strong> · Original fiction${r.familiar?' · Familiar encounter':''}</p>`:''}<p class="apprentice-status" role="status" tabindex="-1" id="apprentice-status"></p>${r?v.page==='show'?showPage(r):v.page==='explain'?explain(r):notice(r):`<h2 id="apprentice-prompt" tabindex="-1">Moss has a comparison to discuss</h2><p>Choose an encounter to open its supplied examples. Your own investigation will wait.</p>${catalog(v)}`}<details id="apprentice-help"${r?.support.includes('help')?' open':''}><summary>Help us think about explanations</summary><p>${help}</p>${hearButton(help,'Hear this help')}${r?button('data-apprentice-together',r.support.includes('together')?'Thinking together recorded':'We thought together'):''}</details>${r?`<p class="tiny">Latest 8 checks stay in each encounter. A ninth demonstration, card check or kept-words record removes the oldest record.</p>${r.checks.length>1?`<details><summary>Earlier records (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>record(r,c,i)).join('')}</details>`:''}<details><summary>Start another encounter</summary>${catalog(v)}</details>`:''}</section>${earlier(v)}</div>`;
}
export function apprenticeNotes(state){const v=apprenticeView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Fair Test apprentice · earlier format</summary><pre>${esc(JSON.stringify(state.fairTests?.apprentice,null,2))}</pre></details>`;return `<details class="panel apprentice-page"><summary>Fair Test apprentice (${v.rounds.length} encounters)</summary><p>Original fiction and authored model examples. Demonstration design, supplied-card feedback and exact ungraded words are separate records; no independent teaching-back, physical experimental competence or prose understanding is inferred.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Familiar: ${r.familiar?'yes':'no'}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${sourceDetails(r)}<p>Current comparison draft:</p>${pairSummary(r.source,r.repair)}<p>Selected supplied card: ${r.selectedCard?esc(r.source.cards.find(x=>x.id===r.selectedCard)?.text||'A supplied explanation'):'none'}.</p><p>Own words draft, ungraded:</p><div class="apprentice-exact">${esc(r.words)}</div>${r.checks.map((c,i)=>record(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindApprentice(state,{save,render,focus}){
 const show=(message='',target='#apprentice-prompt')=>{const id=apprenticeView(state).current?.id,open=[...document.querySelectorAll('.apprentice-sheet details[id][open]:not(#apprentice-help)')].filter(d=>Number(d.dataset.visit)===id).map(d=>d.id);save();render();if(apprenticeView(state).current?.id===id)for(const key of open){const el=document.getElementById(key);if(el)el.open=true;}const status=document.querySelector('#apprentice-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('[data-apprentice-open]',()=>{if(setApprenticeOpen(state,true))show();else{const status=document.querySelector('#fair-apprentice-status');if(status)status.textContent='This saved bench cannot open apprentice work. It remains unchanged.';}});
 bind('[data-apprentice-close]',()=>{const ok=setApprenticeOpen(state,false);if(ok){save();render();focus('[data-apprentice-open]');}});
 bind('[data-apprentice-page]',b=>{const ok=setApprenticePage(state,b.dataset.apprenticePage);show(ok?'':'Choose an encounter first.',ok?'#apprentice-prompt':'#apprentice-status');});
 bind('[data-apprentice-start]',b=>{const r=startApprentice(state,b.dataset.apprenticeStart);show(r?'Moss’s encounter is ready. Your own investigation is unchanged.':'A new encounter cannot be created because its saved visit numbers have reached the supported limit. Existing encounters remain available.',r?'#apprentice-prompt':'#apprentice-status');});
 document.querySelectorAll('[data-apprentice-repair]').forEach(select=>select.addEventListener('change',()=>{const ok=changeApprenticeRepair(state,select.dataset.apprenticeRepair,select.value);show(ok?'Comparison draft changed. Earlier records stay unchanged.':'That setting cannot be used for this encounter.',`#${select.id}`);}));
 bind('[data-apprentice-demonstrate]',()=>{const check=checkApprenticeDemonstration(state);show(check?'This comparison demonstration is recorded.':'This comparison could not be recorded.',check?'.apprentice-record':'#apprentice-status');});
 bind('[data-apprentice-card]',b=>{chooseApprenticeCard(state,b.dataset.apprenticeCard==='clear'?null:b.dataset.apprenticeCard);show('Supplied explanation choice updated. Earlier records stay unchanged.',`[data-apprentice-card="${b.dataset.apprenticeCard}"]`);});
 bind('[data-apprentice-check-card]',()=>{const check=checkApprenticeCard(state);show(check?'The supplied explanation has been shown to Moss.':'Choose a supplied explanation first.',check?'.apprentice-record':'#apprentice-status');});
 bind('[data-apprentice-keep-words]',()=>{const check=keepApprenticeWords(state);show(check?'Your exact words are kept, ungraded.':'Your words could not be kept. The draft remains available.',check?'.apprentice-record':'#apprentice-status');});
 bind('[data-apprentice-resume]',b=>{const ok=resumeApprentice(state,Number(b.dataset.apprenticeResume));show(ok?'Earlier encounter opened with its own source and records.':'That encounter could not be opened.');});
 bind('[data-apprentice-together]',()=>{addApprenticeSupport(state,'together');show('Thinking together recorded.','[data-apprentice-together]');});
 const words=document.querySelector('#apprentice-words');if(words){words.value=apprenticeView(state).current.words;words.addEventListener('input',()=>{const ok=setApprenticeWords(state,words.value),status=document.querySelector('#apprentice-status');if(ok){save();const r=apprenticeView(state).current;document.querySelectorAll('[data-apprentice-record-title]').forEach(el=>{const index=Number(el.dataset.apprenticeRecordTitle),c=r.checks[index];if(c)el.textContent=recordTitle(r,c,index);});}if(status)status.textContent=ok?'Draft updated. Your explanation is ungraded.':'This latest change is not saved. Shorten it to 800 characters in the browser’s text limit to save; your earlier saved draft is unchanged.';});}
 document.querySelector('#apprentice-help')?.addEventListener('toggle',e=>{if(e.currentTarget.open&&apprenticeView(state).current){addApprenticeSupport(state,'help');save();}});
 document.querySelectorAll('.apprentice-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(apprenticeView(state).current){addApprenticeSupport(state,'audio');save();}}));
}
